// Block (composition) — a structured shipping address form.
// Arranges only; composes Form/TextField/Select/Grid/Button/Alert/Stack.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { TextField } from "../components/TextField";
import { Select, SelectItem } from "../components/Select";
import { Grid } from "../layouts/Grid";
import { Button } from "../components/Button";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import "./AddressForm.css";

export interface AddressFormProps {
  /** Heading shown above the address fields. */
  heading?: string;
  /** Called with the submitted address. */
  onSubmit?: (data: Record<string, string>) => void;
  /** Form-level error, shown above the fields. */
  errorMessage?: string;
  /** Puts the submit button in a pending state and blocks re-submit. */
  isPending?: boolean;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function AddressForm({
  heading,
  onSubmit,
  errorMessage,
  isPending,
  className,
  ref,
}: AddressFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      name: String(data.get("name") ?? ""),
      streetAddress: String(data.get("streetAddress") ?? ""),
      city: String(data.get("city") ?? ""),
      state: String(data.get("state") ?? ""),
      postalCode: String(data.get("postalCode") ?? ""),
      country: String(data.get("country") ?? ""),
    });
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-addressform ${className}` : "sd-addressform"}
    >
      <Stack gap="large" className="sd-addressform__content">
        {heading && (
          <>
            <h1 className="sd-addressform__heading sd-type-headline-medium">{heading}</h1>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack gap="medium" className="sd-addressform__fields">
          <TextField label="Full name" name="name" autoComplete="name" isRequired />
          <TextField
            label="Street address"
            name="streetAddress"
            autoComplete="street-address"
            isRequired
          />
          <Grid columns={{ small: 1, medium: 3 }} gap="medium">
            <TextField label="City" name="city" autoComplete="address-level2" isRequired />
            <TextField label="State" name="state" autoComplete="address-level1" isRequired />
            <TextField label="ZIP" name="postalCode" autoComplete="postal-code" isRequired />
          </Grid>
          <Select label="Country" name="country" defaultSelectedKey="us" isRequired>
            <SelectItem id="us">United States</SelectItem>
            <SelectItem id="ca">Canada</SelectItem>
            <SelectItem id="gb">United Kingdom</SelectItem>
            <SelectItem id="au">Australia</SelectItem>
            <SelectItem id="kr">South Korea</SelectItem>
          </Select>
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Save
        </Button>
      </Stack>
    </Form>
  );
}

/* AddressForm.css — arrangement only; responsive fields use Grid props. */
/* Fills the column it is given. Its city, state and ZIP share one row from the medium step, so the
   page gives it a wider span than a single-purpose form. */
.sd-addressform {
  width: 100%;
}

.sd-addressform__heading {
  margin: 0;
}
